    contains_space_divider = " " in input_string
    contains_t_divider = "T" in input_string

    space_count = input_string.count(" ")
    if contains_space_divider and space_count != 1 or contains_t_divider and space_count > 0:
        raise ParserError(
            "Expected an ISO 8601-like string, but was given '{}'. Try passing in a format string to resolve this.".format(
                input_string
            )
        )

    includes_time = contains_space_divider or contains_t_divider
    has_timezone = False

    # date formats (ISO 8601 and others) to test against
    # NOTE: YYYYMM is omitted to avoid confusion with YYMMDD (no longer part of ISO 8601, but is still often used)
    base_formats = [
        "YYYY-MM-DD",
        "YYYY-M-DD",
        "YYYY-M-D",
        "YYYY/MM/DD",
        "YYYY/M/DD",
        "YYYY/M/D",
        "YYYY.MM.DD",
        "YYYY.M.DD",
        "YYYY.M.D",
        "YYYYMMDD",
        "YYYY-DDDD",
        "YYYYDDDD",
        "YYYY-MM",
        "YYYY/MM",
        "YYYY.MM",
        "YYYY",
        "W",
    ]

    if includes_time:
        if contains_space_divider:
            date_part, time_part = input_string.split(" ", 1)
        else:
            date_part, time_part = input_string.split("T", 1)

        time_components_list = re.split(r"[\\+\-Z]", time_part, 1, re.IGNORECASE)

        time_match = self._TIME_RE.match(time_components_list[0])

        if time_match is None:
            raise ParserError(
                "Invalid time component provided. Please specify a format or provide a valid time component in the basic or extended ISO 8601 time format."
            )

        matched_hours, matched_minutes, matched_seconds, subseconds_separator, matched_subseconds = time_match.groups()

        has_timezone = len(time_components_list) == 2
        has_minutes = matched_minutes is not None
        has_seconds = matched_seconds is not None
        has_subseconds = matched_subseconds is not None

        is_basic_format = ":" not in time_components_list[0]
        tz_token = "Z"

        # use 'ZZ' token instead since tz offset is present in non-basic format
        if has_timezone and ":" in time_components_list[1]:
            tz_token = "ZZ"

        time_separator = "" if is_basic_format else ":"

        if has_subseconds:
            constructed_time = "HH{time_sep}mm{time_sep}ss{subseconds_sep}S".format(
                time_sep=time_separator, subseconds_sep=subseconds_separator
            )
        elif has_seconds:
            constructed_time = "HH{time_sep}mm{time_sep}ss".format(time_sep=time_separator)
        elif has_minutes:
            constructed_time = "HH{time_sep}mm".format(time_sep=time_separator)
        else:
            constructed_time = "HH"

        final_formats = []
        for base_fmt in base_formats:
            if contains_space_divider:
                combined = "{} {}".format(base_fmt, constructed_time)
            else:
                combined = "{}T{}".format(base_fmt, constructed_time)
            final_formats.append(combined)

    if includes_time and has_timezone:
        # Add "Z" or "ZZ" to the format strings to indicate to
        # _parse_token() that a timezone needs to be parsed
        updated_formats = []
        for fmt in final_formats:
            appended = "{}{}".format(fmt, tz_token)
            updated_formats.append(appended)
        final_formats = updated_formats

    return self._parse_multiformat(input_string, final_formats)
