            time_template = "HH{time_sep}mm{time_sep}ss".format(time_sep=time_sep_char)
        elif has_minutes:
            time_template = "HH{time_sep}mm".format(time_sep=time_sep_char)
        else:
            time_template = "HH"

        candidate_formats = []
        for base_fmt in candidate_formats:
            if contains_space_divider:
                combined_fmt = "{} {}".format(base_fmt, time_template)
            else:
