        # _parse_token() that a timezone needs to be parsed
        updated_formats = []
        for fmt in candidate_formats:
            appended_fmt = "{}{}".format(fmt, tz_token)
            updated_formats.append(appended_fmt)
        candidate_formats = updated_formats

