```python
def _format_token(self, input_datetime, format_token):
    if format_token and format_token.startswith("[") and format_token.endswith("]"):
        stripped_format = format_token[1:-1]
        return stripped_format

    if format_token == "YYYY":
        return self.locale.year_full(input_datetime.year)
    if format_token == "YY":
        return self.locale.year_abbreviation(input_datetime.year)

    if format_token == "MMMM":
        return self.locale.month_name(input_datetime.month)
    if format_token == "MMM":
        return self.locale.month_abbreviation(input_datetime.month)
    if format_token == "MM":
        return "{:02d}".format(input_datetime.month)
    if format_token == "M":
        return str(input_datetime.month)

    if format_token == "DDDD":
        return "{:03d}".format(input_datetime.timetuple().tm_yday)
    if format_token == "DDD":
        return str(input_datetime.timetuple().tm_yday)
    if format_token == "DD":
        return "{:02d}".format(input_datetime.day)
    if format_token == "D":
        return str(input_datetime.day)

    if format_token == "Do":
        return self.locale.ordinal_number(input_datetime.day)

    if format_token == "dddd":
        return self.locale.day_name(input_datetime.isoweekday())
    if format_token == "ddd":
        return self.locale.day_abbreviation(input_datetime.isoweekday())
    if format_token == "d":
        return str(input_datetime.isoweekday())

    if format_token == "HH":
        return "{:02d}".format(input_datetime.hour)
    if format_token == "H":
        return str(input_datetime.hour)

    adjusted_hour = input_datetime.hour if 0 < input_datetime.hour < 13 else abs(input_datetime.hour - 12)
    if format_token == "hh":
        return "{:02d}".format(adjusted_hour)
    if format_token == "h":
        return str(adjusted_hour)

    if format_token == "mm":
        return "{:02d}".format(input_datetime.minute)
    if format_token == "m":
        return str(input_datetime.minute)

    if format_token == "ss":
        return "{:02d}".format(input_datetime.second)
    if format_token == "s":
        return str(input_datetime.second)

    if format_token == "SSSSSS":
        return str("{:06d}".format(int(input_datetime.microsecond)))
    if format_token == "SSSSS":
        return str("{:05d}".format(int(input_datetime.microsecond / 10)))
    if format_token == "SSSS":
        return str("{:04d}".format(int(input_datetime.microsecond / 100)))
    if format_token == "SSS":
        return str("{:03d}".format(int(input_datetime.microsecond / 1000)))
    if format_token == "SS":
        return str("{:02d}".format(int(input_datetime.microsecond / 10000)))
    if format_token == "S":
        return str(int(input_datetime.microsecond / 100000))

    if format_token == "X":
        # TODO: replace with a call to dt.timestamp() when we drop Python 2.7
        return str(calendar.timegm(input_datetime.utctimetuple()))

    if format_token == "x":
        # TODO: replace with a call to dt.timestamp() when we drop Python 2.7
        timestamp_seconds = calendar.timegm(input_datetime.utctimetuple()) + (input_datetime.microsecond / 1000000)
        return str(int(timestamp_seconds * 1000000))

    if format_token == "ZZZ":
        return input_datetime.tzname()

    if format_token in ["ZZ", "Z"]:
        separator_character = ":" if format_token == "ZZ" else ""
        timezone_info = dateutil_tz.tzutc() if input_datetime.tzinfo is None else input_datetime.tzinfo
        total_offset_minutes = int(util.total_seconds(timezone_info.utcoffset(input_datetime)) / 60)

        sign_indicator = "+" if total_offset_minutes >= 0 else "-"
        absolute_offset_minutes = abs(total_offset_minutes)
        offset_hour, offset_minute = divmod(absolute_offset_minutes, 60)

        return "{}{:02d}{}{:02d}".format(sign_indicator, offset_hour, separator_character, offset_minute)

    if format_token in ("a", "A"):
        return self.locale.meridian(input_datetime.hour, format_token)

    if format_token == "W":
        iso_year, iso_week, iso_day = input_datetime.isocalendar()
        return "{}-W{:02d}-{}".format(iso_year, iso_week, iso_day)
```
