def parse_iso(self, input_string):
    # TODO: add a flag to normalize whitespace (useful in logs, ref issue #421)
    contains_space_divider = " " in input_string
    contains_t_divider = "T" in input_string

    space_count = input_string.count(" ")
    if contains_space_divider and space_count != 1 or contains_t_divider and space_count > 0:
        raise ParserError(
            "Expected an ISO 8601-like string, but was given '{}'. Try passing in a format string to resolve this.".format(
                input_string
            )
        )

    includes_time = contains_space_divider or contains_t_divider
    has_timezone = False

    # date formats (ISO 8601 and others) to test against
    # NOTE: YYYYMM is omitted to avoid confusion with YYMMDD (no longer part of ISO 8601, but is still often used)
    candidate_formats = [
        "YYYY-MM-DD",
        "YYYY-M-DD",
        "YYYY-M-D",
        "YYYY/MM/DD",
        "YYYY/M/DD",
        "YYYY/M/D",
        "YYYY.MM.DD",
        "YYYY.M.DD",
        "YYYY.M.D",
        "YYYYMMDD",
        "YYYY-DDDD",
        "YYYYDDDD",
        "YYYY-MM",
        "YYYY/MM",
        "YYYY.MM",
        "YYYY",
        "W",
    ]

    if includes_time:
        if contains_space_divider:
            date_segment, time_segment = input_string.split(" ", 1)
        else:
            date_segment, time_segment = input_string.split("T", 1)

        time_parts_array = re.split(r"[\\+\-Z]", time_segment, 1, re.IGNORECASE)

        time_match_result = self._TIME_RE.match(time_parts_array[0])

        if time_match_result is None:
            raise ParserError(
                "Invalid time component provided. Please specify a format or provide a valid time component in the basic or extended ISO 8601 time format."
            )

        matched_h, matched_m, matched_s, subsec_sep, matched_subsec = time_match_result.groups()

        has_timezone = len(time_parts_array) == 2
        has_minutes = matched_m is not None
        has_seconds = matched_s is not None
        has_subseconds = matched_subsec is not None

        is_basic_style = ":" not in time_parts_array[0]
        tz_token = "Z"

        # use 'ZZ' token instead since tz offset is present in non-basic format
        if has_timezone and ":" in time_parts_array[1]:
            tz_token = "ZZ"

        time_sep_char = "" if is_basic_style else ":"

        if has_subseconds:
            time_template = "HH{time_sep}mm{time_sep}ss{subseconds_sep}S".format(
                time_sep=time_sep_char, subseconds_sep=subsec_sep
            )
        elif has_seconds:
            time_template = "HH{time_sep}mm{time_sep}ss".format(time_sep=time_sep_char)
        elif has_minutes:
            time_template = "HH{time_sep}mm".format(time_sep=time_sep_char)
        else:
            time_template = "HH"

        candidate_formats = []
        for base_fmt in candidate_formats:
            if contains_space_divider:
                combined_fmt = "{} {}".format(base_fmt, time_template)
            else:
                combined_fmt = "{}T{}".format(base_fmt, time_template)
            candidate_formats.append(combined_fmt)

    if includes_time and has_timezone:
        # Add "Z" or "ZZ" to the format strings to indicate to
        # _parse_token() that a timezone needs to be parsed
        updated_formats = []
        for fmt in candidate_formats:
            appended_fmt = "{}{}".format(fmt, tz_token)
            updated_formats.append(appended_fmt)
        candidate_formats = updated_formats

    return self._parse_multiformat(input_string, candidate_formats)
