def _parse_token(self, format_token, raw_value, target_parts):

    if format_token == "YYYY":
        target_parts["year"] = int(raw_value)

    elif format_token == "YY":
        parsed_year = int(raw_value)
        target_parts["year"] = 1900 + parsed_year if parsed_year > 68 else 2000 + parsed_year

    elif format_token in ["MMMM", "MMM"]:
        target_parts["month"] = self.locale.month_number(raw_value.lower())

    elif format_token in ["MM", "M"]:
        target_parts["month"] = int(raw_value)

    elif format_token in ["DDDD", "DDD"]:
        target_parts["day_of_year"] = int(raw_value)

    elif format_token in ["DD", "D"]:
        target_parts["day"] = int(raw_value)

    elif format_token in ["Do"]:
        target_parts["day"] = int(raw_value)

    elif format_token.upper() in ["HH", "H"]:
        target_parts["hour"] = int(raw_value)

    elif format_token in ["mm", "m"]:
        target_parts["minute"] = int(raw_value)

    elif format_token in ["ss", "s"]:
        target_parts["second"] = int(raw_value)

    elif format_token == "S":
        # We have the *most significant* digits of an arbitrary-precision integer.
        # We want the six most significant digits as an integer, rounded.
        # IDEA: add nanosecond support somehow? Need datetime support for it first.
        padded_value = raw_value.ljust(7, str("0"))

        # floating-point (IEEE-754) defaults to half-to-even rounding
        seventh_digit = int(padded_value[6])
        if seventh_digit == 5:
            rounding_adjustment = int(padded_value[5]) % 2
        elif seventh_digit > 5:
            rounding_adjustment = 1
        else:
            rounding_adjustment = 0

        target_parts["microsecond"] = int(padded_value[:6]) + rounding_adjustment

    elif format_token == "X":
        target_parts["timestamp"] = float(raw_value)

    elif format_token == "x":
        target_parts["expanded_timestamp"] = int(raw_value)

    elif format_token in ["ZZZ", "ZZ", "Z"]:
        target_parts["tzinfo"] = TzinfoParser.parse(raw_value)

    elif format_token in ["a", "A"]:
        if raw_value in (self.locale.meridians["am"], self.locale.meridians["AM"]):
            target_parts["am_pm"] = "am"
        elif raw_value in (self.locale.meridians["pm"], self.locale.meridians["PM"]):
            target_parts["am_pm"] = "pm"

    elif format_token == "W":
        target_parts["weekdate"] = raw_value
```
