@staticmethod
def _build_datetime(parts_dict):

    weekdate_value = parts_dict.get("weekdate")

    if weekdate_value is not None:
        # we can use strptime (%G, %V, %u) in python 3.6 but these tokens aren't available before that
        year_component = int(weekdate_value[0])
        week_component = int(weekdate_value[1])

        if weekdate_value[2] is not None:
            day_component = int(weekdate_value[2])
        else:
            # day not given, default to 1
            day_component = 1

        converted_dt = iso_to_gregorian(year_component, week_component, day_component)
        parts_dict["year"] = converted_dt.year
        parts_dict["month"] = converted_dt.month
        parts_dict["day"] = converted_dt.day

    timestamp_value = parts_dict.get("timestamp")

    if timestamp_value is not None:
        return datetime.fromtimestamp(timestamp_value, tz=tz.tzutc())

    expanded_ts_value = parts_dict.get("expanded_timestamp")

    if expanded_ts_value is not None:

        if expanded_ts_value > MAX_TIMESTAMP:
            if expanded_ts_value < MAX_TIMESTAMP_MS:
                expanded_ts_value /= 1000.0
            elif expanded_ts_value < MAX_TIMESTAMP_US:
                expanded_ts_value /= 1000000.0
            else:
                raise ValueError(
                    "The specified timestamp '{}' is too large.".format(
                        expanded_ts_value
                    )
                )

        return datetime.fromtimestamp(expanded_ts_value, tz=tz.tzutc())

    day_of_year_value = parts_dict.get("day_of_year")

    if day_of_year_value is not None:
        year_val = parts_dict.get("year")
        month_val = parts_dict.get("month")
        if year_val is None:
            raise ParserError(
                "Year component is required with the DDD and DDDD tokens."
            )

        if month_val is not None:
            raise ParserError(
                "Month component is not allowed with the DDD and DDDD tokens."
            )

        date_str = "{}-{}".format(year_val, day_of_year_value)
        try:
            parsed_date = datetime.strptime(date_str, "%Y-%j")
        except ValueError:
            raise ParserError(
                "The provided day of year '{}' is invalid.".format(day_of_year_value)
            )

        parts_dict["year"] = parsed_date.year
        parts_dict["month"] = parsed_date.month
        parts_dict["day"] = parsed_date.day

    am_pm_value = parts_dict.get("am_pm")
    hour_val = parts_dict.get("hour", 0)

    if am_pm_value == "pm" and hour_val < 12:
        hour_val += 12
    elif am_pm_value == "am" and hour_val == 12:
        hour_val = 0

    # Support for midnight at the end of day
    if hour_val == 24:
        if parts_dict.get("minute", 0) != 0:
            raise ParserError("Midnight at the end of day must not contain minutes")
        if parts_dict.get("second", 0) != 0:
            raise ParserError("Midnight at the end of day must not contain seconds")
        if parts_dict.get("microsecond", 0) != 0:
            raise ParserError(
                "Midnight at the end of day must not contain microseconds"
            )
        hour_val = 0
        day_increment = 1
    else:
        day_increment = 0

    # account for rounding up to 1000000
    microsecond_val = parts_dict.get("microsecond", 0)
    if microsecond_val == 1000000:
        microsecond_val = 0
        second_increment = 1
    else:
        second_increment = 0

    increment_delta = timedelta(days=day_increment, seconds=second_increment)

    return (
        datetime(
            year=parts_dict.get("year", 1),
            month=parts_dict.get("month", 1),
            day=parts_dict.get("day", 1),
            hour=hour_val,
            minute=parts_dict.get("minute", 0),
            second=parts_dict.get("second", 0),
            microsecond=microsecond_val,
            tzinfo=parts_dict.get("tzinfo"),
        )
        + increment_delta
    )
